def _redact_text(value, no_log_strings):
    native = to_native(value, errors='surrogate_or_strict')
    for secret in no_log_strings:
        native = native.replace(secret, '********')
    if isinstance(value, binary_type) and not isinstance(native, binary_type):
        return to_bytes(native, errors='surrogate_then_replace')
    if isinstance(value, text_type) and not isinstance(native, text_type):
        return to_text(native, errors='surrogate_then_replace')
    return native


def _copy_redacted_container(value, children, keys=None):
    if isinstance(value, Mapping):
        pairs = zip(keys, children)
        if isinstance(value, MutableMapping):
            result = copy.copy(value)
            result.clear()
            result.update(pairs)
            return result
        return type(value)(dict(pairs))
    if isinstance(value, MutableSequence):
        result = copy.copy(value)
        del result[:]
        result.extend(children)
        return result
    if isinstance(value, tuple) and hasattr(value, '_fields'):
        return type(value)(*children)
    if isinstance(value, Sequence):
        return type(value)(children)
    if isinstance(value, MutableSet):
        result = copy.copy(value)
        result.clear()
        result.update(children)
        return result
    return type(value)(children)


def _redact_structure(obj, no_log_strings, keys_only=False, ignore_keys=frozenset()):
    """Copy nested containers iteratively, changing only the requested strings."""
    secrets = sorted(set(to_native(s, errors='surrogate_or_strict') for s in no_log_strings if s),
                     key=lambda s: (-len(s), s))
    pending = [(obj, False)]
    completed = []

    while pending:
        value, closing = pending.pop()
        is_mapping = isinstance(value, Mapping)
        is_sequence = isinstance(value, Sequence) and not isinstance(value, (text_type, binary_type))
        is_set = isinstance(value, Set)
        if closing:
            count = len(value)
            children = completed[-count:] if count else []
            if count:
                del completed[-count:]
            if is_mapping:
                transformed_keys = []
                for key in value:
                    if keys_only and isinstance(key, (text_type, binary_type)):
                        native_key = to_native(key, errors='surrogate_or_strict')
                        if native_key not in ignore_keys and not native_key.startswith('_ansible'):
                            if native_key in secrets:
                                key = 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'
                            else:
                                key = _redact_text(key, secrets)
                    transformed_keys.append(key)
                completed.append(_copy_redacted_container(value, children, transformed_keys))
            else:
                completed.append(_copy_redacted_container(value, children))
        elif is_mapping or is_sequence or is_set:
            pending.append((value, True))
            elements = value.values() if is_mapping else value
            for child in reversed(list(elements)):
                pending.append((child, False))
        elif not keys_only and isinstance(value, (text_type, binary_type)):
            completed.append(_redact_text(value, secrets))
        else:
            completed.append(value)
    return completed[0]


def remove_values(value, no_log_strings):
    """Mask sensitive substrings in values, retaining mapping keys and types."""
    return _redact_structure(value, no_log_strings)


def sanitize_keys(obj, no_log_strings, ignore_keys=frozenset()):
    """Mask sensitive mapping keys throughout a nested container."""
    return _redact_structure(obj, no_log_strings, keys_only=True, ignore_keys=ignore_keys)


